```javascript
const fs = require('fs/promises');
const path = require('path');

/**
 * Loads and validates a JSON config file within an allowed directory.
 *
 * @param {string} baseDir - The allowed root directory.
 * @param {string} userPath - User-supplied relative path to the config file.
 * @returns {Promise<Object>} The parsed and validated config object.
 * @throws {Error} If path escapes baseDir, file cannot be read/parsed, or required fields are missing.
 */
async function loadConfig(baseDir, userPath) {
  if (typeof baseDir !== 'string' || typeof userPath !== 'string') {
    throw new TypeError('Both baseDir and userPath must be strings.');
  }

  // 1. Resolve paths to prevent directory traversal attacks (e.g. '../../etc/passwd')
  const resolvedBase = path.resolve(baseDir);
  const targetPath = path.resolve(resolvedBase, userPath);

  const relative = path.relative(resolvedBase, targetPath);
  const isOutsideBase = relative.startsWith('..') || path.isAbsolute(relative);

  if (isOutsideBase) {
    throw new Error('Access denied: path is outside the allowed directory.');
  }

  // 2. Read file content
  let rawContent;
  try {
    rawContent = await fs.readFile(targetPath, 'utf8');
  } catch (err) {
    throw new Error(`Failed to read config file at "${userPath}": ${err.message}`);
  }

  // 3. Parse JSON
  let config;
  try {
    config = JSON.parse(rawContent);
  } catch (err) {
    throw new Error(`Invalid JSON syntax in "${userPath}": ${err.message}`);
  }

  if (typeof config !== 'object' || config === null || Array.isArray(config)) {
    throw new Error('Invalid configuration: root JSON value must be an object.');
  }

  // 4. Validate required fields (dbHost, dbPort)
  const { dbHost, dbPort } = config;

  if (typeof dbHost !== 'string' || dbHost.trim() === '') {
    throw new Error('Validation error: "dbHost" is required and must be a non-empty string.');
  }

  const port = Number(dbPort);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error('Validation error: "dbPort" is required and must be an integer between 1 and 65535.');
  }

  return config;
}

module.exports = { loadConfig };
```

