import { readFile, realpath } from 'node:fs/promises';
import path from 'node:path';

/**
 * Validates that a port number is an integer in the valid TCP/UDP range.
 * @param {unknown} port
 * @returns {boolean}
 */
function isValidPort(port) {
  return (
    typeof port === 'number' &&
    Number.isInteger(port) &&
    port >= 1 &&
    port <= 65535
  );
}

/**
 * Validates that a host is a non-empty string.
 * @param {unknown} host
 * @returns {boolean}
 */
function isValidHost(host) {
  return typeof host === 'string' && host.trim().length > 0;
}

/**
 * Reads and parses a JSON configuration file within an allowed directory.
 *
 * @param {string} userPath - User-provided relative path to the config file.
 * @param {string} baseDir - Absolute or relative path to the allowed base directory.
 * @returns {Promise<Record<string, unknown>>} Parsed configuration object.
 * @throws {Error} If path escapes baseDir, file is missing, JSON is invalid, or schema fails.
 */
export async function loadConfig(userPath, baseDir) {
  if (typeof userPath !== 'string' || userPath.trim().length === 0) {
    throw new TypeError('userPath must be a non-empty string.');
  }
  if (typeof baseDir !== 'string' || baseDir.trim().length === 0) {
    throw new TypeError('baseDir must be a non-empty string.');
  }

  // 1. Resolve normalized absolute paths
  const resolvedBase = path.resolve(baseDir);
  const targetPath = path.resolve(resolvedBase, userPath);

  // 2. Prevent logical path traversal (e.g., ../../etc/passwd)
  const relativePath = path.relative(resolvedBase, targetPath);
  if (relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
    throw new Error('Access denied: target path escapes the allowed base directory.');
  }

  // 3. Resolve real paths to prevent symlink traversal attacks
  const [realBase, realTarget] = await Promise.all([
    realpath(resolvedBase),
    realpath(targetPath),
  ]);

  const realRelative = path.relative(realBase, realTarget);
  if (realRelative.startsWith('..') || path.isAbsolute(realRelative)) {
    throw new Error('Access denied: target resolves outside the allowed base directory via symlink.');
  }

  // 4. Read file content
  const rawData = await readFile(realTarget, { encoding: 'utf8' });

  // 5. Parse JSON
  let config;
  try {
    config = JSON.parse(rawData);
  } catch (err) {
    throw new Error(`Invalid JSON in configuration file "${userPath}": ${err.message}`);
  }

  // 6. Validate object shape
  if (config === null || typeof config !== 'object' || Array.isArray(config)) {
    throw new TypeError('Configuration root must be a JSON object.');
  }

  // 7. Validate required fields
  if (!('dbHost' in config) || !isValidHost(config.dbHost)) {
    throw new Error('Invalid configuration: "dbHost" is required and must be a non-empty string.');
  }

  if (!('dbPort' in config) || !isValidPort(config.dbPort)) {
    throw new Error('Invalid configuration: "dbPort" is required and must be an integer between 1 and 65535.');
  }

  return config;
}
